def check(row):
    start, end = 0, len(row) - 1
    while start < len(row) and row[start] == 0:
        start += 1

    if start >= len(row):
        return True, True

    while end >= start and row[end] == 0:
        end -= 1

    for i in range(start, end):
        if row[i] == 0:
            return False, False

    return True, False


