        memo[t] = list(ps)[0] + 1
        return memo[t]

    def _path(tt,ss):
        q = [(tt,ss)]
        tq = []
        qi = 0
        while len(q) > qi:
            t,s = q[qi]
            for k in d[t]:
                if k == s:
                    continue
                q.append((k,t))
            qi += 1
        for t,s in q[::-1]:
            r = path(t,s)
            if r < 0:
                return r
        return memo[tt]

    def _path2(tt,ss):
        q = [(tt,ss)]
        tq = []
        qi = 0
        while len(q) > qi:
            t,s = q[qi]
            for k in d[t]:
                if k == s or memo[k] >= 0:
                    continue
                q.append((k,t))
            qi += 1
        for t,s in q[::-1]:
            r = path(t,s)
            if r < 0:
                return r
        return memo[tt]

    t = _path(1,-1)
    if t < 0:
        t = _path2(-t,-1)

    if t > 0:
        while t%2 == 0:
            t//=2
        return t

    return -1

